class Store {
  count = 0
  async load(x) { return x; }
  static create() { return new Store(); }
  get value() { return this.count; }
}

class Store {
  count = 0
  static create(): Store { return new Store(); }
  limit: number = 10
  async load(x: number): Promise<number> { return x; }
  name = 'a'
  get value(): number { return this.count; }
}

